import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.iXqqCa-C.js";const _=JSON.parse('{"title":"规则","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/rules.md","filePath":"guide/agent/rules.md","lastUpdated":1793501934000}'),i={name:"guide/agent/rules.md"};function d(o,a,n,h,s,u){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h1><p>规则是角色作者为角色设定的行为约束。与人设中的<a href="/guide/agent/create#人设">禁止行为</a>不同，部分规则可以由用户在会话中开关。</p><h2 id="规则类型" tabindex="-1">规则类型 <a class="header-anchor" href="#规则类型" aria-label="Permalink to &quot;规则类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>常驻规则</td><td>始终生效，用户无法关闭</td></tr><tr><td>可切换规则</td><td>用户可在会话中开启或关闭，作者可设置默认状态</td></tr></tbody></table><p>可切换规则可以另填「关闭状态提示词」：开启时注入开启提示词，关闭时注入关闭提示词，列表中显示「双向」标记。没有填写关闭提示词的规则，关闭后不注入任何内容。</p><h2 id="会话中的「规则」标签页" tabindex="-1">会话中的「规则」标签页 <a class="header-anchor" href="#会话中的「规则」标签页" aria-label="Permalink to &quot;会话中的「规则」标签页&quot;">​</a></h2><ul><li>顶部显示规则总数、常驻数和可切换数。</li><li>每条规则显示名称、简介和当前状态，可切换规则带开关。</li><li>开关即时保存，下一轮对话起生效。</li><li>只显示名称和简介，不显示规则内容。</li><li>角色没有配置规则时显示「当前会话使用的角色没有配置规则」。</li></ul><h2 id="创作者配置" tabindex="-1">创作者配置 <a class="header-anchor" href="#创作者配置" aria-label="Permalink to &quot;创作者配置&quot;">​</a></h2><p>在<a href="/guide/agent/create#规则">角色编辑页</a>的「规则」部分配置：</p><ul><li>每个角色最多 5 条，名称和简介各不超过 50 字。</li><li>字段：规则名称、简介（向用户说明作用）、类型、规则内容（可切换规则称为「开启状态提示词」）、关闭状态提示词（可选）、是否默认开启。</li><li>规则随角色版本发布，修改后需要重新发布才会对社区会话生效。</li></ul>',10)])])}const p=t(i,[["render",d]]);export{_ as __pageData,p as default};
